import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"TaskFlow API — Production-grade FastAPI Backend","description":"A task-management REST API built like production: JWT rotation with reuse detection, RBAC, rate limiting, Redis caching, pytest suite and Docker Compose.","frontmatter":{"title":"TaskFlow API — Production-grade FastAPI Backend","description":"A task-management REST API built like production: JWT rotation with reuse detection, RBAC, rate limiting, Redis caching, pytest suite and Docker Compose."},"headers":[],"relativePath":"en/projects/taskflow-api/index.md","filePath":"en/projects/taskflow-api/index.md"}`),a={name:`en/projects/taskflow-api/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="taskflow-api-—-production-grade-fastapi-backend" tabindex="-1">TaskFlow API — Production-grade FastAPI Backend <a class="header-anchor" href="#taskflow-api-—-production-grade-fastapi-backend" aria-label="Permalink to “TaskFlow API — Production-grade FastAPI Backend”">​</a></h1><p><strong><a href="https://github.com/Godde3s/taskflow-api" target="_blank" rel="noreferrer">TaskFlow API</a></strong> is my reference answer to a question interviewers actually ask: <em>what does &quot;production-grade&quot; mean in your backend code?</em> Instead of answering with adjectives, I shipped the repository — a task-management API where every security claim is implemented <strong>and</strong> covered by tests.</p><h2 id="security-that-is-tested-not-promised" tabindex="-1">Security that is tested, not promised <a class="header-anchor" href="#security-that-is-tested-not-promised" aria-label="Permalink to “Security that is tested, not promised”">​</a></h2><p>Most repos mention JWT and move on. TaskFlow implements the parts that actually matter:</p><table tabindex="0"><thead><tr><th>Control</th><th>Implementation</th></tr></thead><tbody><tr><td>Password storage</td><td>bcrypt, cost 12, per-user salt</td></tr><tr><td>Access tokens</td><td>15-minute TTL, signed HS256</td></tr><tr><td>Refresh tokens</td><td>7-day rotation with <strong>family reuse detection</strong> — replaying an old refresh token kills the whole token family</td></tr><tr><td>Authorization</td><td>RBAC guards as FastAPI dependencies — <code>require_admin</code>, ownership checks on every task operation</td></tr><tr><td>Abuse resistance</td><td>Sliding-window login rate limiter → <code>429</code> with <code>Retry-After</code></td></tr><tr><td>Ops hygiene</td><td>Generic 500s (no stack traces), <code>X-Request-ID</code> correlation, security headers, non-root Docker image</td></tr></tbody></table><p>The refresh-rotation test is my favorite: it logs in, rotates, replays the old token expecting <code>401</code>, then verifies the <em>new</em> token is dead too — because a replayed token means theft, and theft means revoke everything.</p><h2 id="engineering-decisions-worth-stealing" tabindex="-1">Engineering decisions worth stealing <a class="header-anchor" href="#engineering-decisions-worth-stealing" aria-label="Permalink to “Engineering decisions worth stealing”">​</a></h2><ul><li><strong>Routers thin, services fat</strong> — the HTTP layer parses and serializes; business rules live where they are unit-testable.</li><li><strong>Async SQLAlchemy 2.0 + Pydantic v2 settings</strong> — 12-factor config; SQLite locally, PostgreSQL in compose.</li><li><strong>Docker Compose</strong> with health-checked <code>postgres:16</code> and <code>redis:7</code> — <code>docker compose up</code> is the whole install guide.</li><li><strong>A pytest suite that runs in seconds</strong> — in-memory async database, no containers needed for CI.</li></ul><div class="tip custom-block"><p class="custom-block-title">Try it</p><p><code>docker compose up --build</code> then open <code>/docs</code> — the interactive OpenAPI playground: <a href="https://github.com/Godde3s/taskflow-api" target="_blank" rel="noreferrer">github.com/Godde3s/taskflow-api</a></p></div><h2 id="what-i-learned-building-it" tabindex="-1">What I learned building it <a class="header-anchor" href="#what-i-learned-building-it" aria-label="Permalink to “What I learned building it”">​</a></h2><p>The subtle part was not FastAPI — it was deciding what &quot;done&quot; means: migration path, rate-limit semantics under multi-instance deployment (swap the in-process buckets for Redis), and documentation that explains <em>why</em> the trade-offs exist rather than hiding them. That philosophy is written down in the repository&#39;s <code>SECURITY.md</code>.</p>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};